  count: number;
  orgEvents: OrganizerEvent[];
}

// --- 3. The API Definition ---
export const organizerApi = createApi({
  reducerPath: "organizerApi",
  tagTypes: ["Organizer", "Event", "User"], 
  baseQuery: axiosBaseQuery(),
  endpoints: (builder) => ({
    // --- Organizer Endpoints ---
