        method: "POST",
        data: credentials,
      }),
      invalidatesTags: ["Organizer"], 
    }),
    getOrganizer: builder.query<any, void>({
      query: () => ({
        url: "auth/getuser",
        method: "POST",
      }),
      providesTags: ["Organizer"],
    }),

    // --- Event Endpoints ---
    fetchOrganizerEvents: builder.query<OrganizerEventsResponse, void>({
      query: () => ({ 
        url: "organizers/fetchorganizersevents", 
        method: "GET" 
      }),
      providesTags: (result) =>
