} from '@mui/material';
import type { Branding } from '@toolpad/core';

// ─── Props Interface ────────────────────────────────────────────────────────
interface SignupFormProps {
  branding?: Branding;
  onSignup: (formData: {
    name: string;        // ← Concatenated firstName + lastName
    email: string;
    password: string;
    confirmPassword: string;
  }) => Promise<{ error?: string } | void>;
  darkMode?: boolean;   // ← Controlled from User_Signup.tsx
  title?: string;
}

// ─── Default Values ─────────────────────────────────────────────────────────
const DEFAULT_BRANDING: Branding = {
  logo: (
    <img src="/logo192.png" alt="Ticket App Logo" style={{ height: 24 }} />
  ),
  title: 'Ticket Booking',
};

// ─── Component ──────────────────────────────────────────────────────────────
export default function SignupForm({
  branding = DEFAULT_BRANDING,
  onSignup,
  darkMode = false,
  title,
}: SignupFormProps) {

  // ── Field States ──────────────────────────────────────────────────────
  const [firstName, setFirstName] = React.useState('');
  const [lastName, setLastName]   = React.useState('');
  const [email, setEmail]         = React.useState('');
  const [password, setPassword]   = React.useState('');
  const [confirmPassword, setConfirmPassword] = React.useState('');
  const [error, setError]         = React.useState('');
  const [isLoading, setIsLoading] = React.useState(false);

  // ── Concatenated name ─────────────────────────────────────────────────
  const name = `${firstName.trim()} ${lastName.trim()}`.trim();

  // ── Password match check ──────────────────────────────────────────────
  const passwordsMatch = password === confirmPassword;
  const confirmPasswordError = !!confirmPassword && !passwordsMatch;

  // ── Button disabled logic ─────────────────────────────────────────────
  const isButtonDisabled =
    !firstName.trim()     ||   // First name empty
    !lastName.trim()      ||   // Last name empty
    !email.trim()         ||   // Email empty
    !password.trim()      ||   // Password empty
    !confirmPassword.trim() || // Confirm password empty
    !passwordsMatch       ||   // Passwords don't match
    isLoading;                 // Request in progress

  // ── Theme (controlled via darkMode prop from User_Signup.tsx) ─────────
  const theme = React.useMemo(
    () =>
      createTheme({
        palette: {
          mode: darkMode ? 'dark' : 'light',
        },
      }),
    [darkMode]
  );

  // ── Submit Handler ────────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }

    setIsLoading(true);
    try {
      const result = await onSignup({ name, email, password, confirmPassword });
      if (result?.error) {
        setError(result.error);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />

      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: '100vh',
        }}
      >
        <Paper
          elevation={3}
          sx={{ p: 4, width: '100%', maxWidth: 400, borderRadius: 2 }}
        >
          {/* ── Logo ──────────────────────────────────────────────────── */}
          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
            {branding.logo}
          </Box>

          {/* ── Title ─────────────────────────────────────────────────── */}
          {title && (
            <Typography
              variant="h5"
              fontWeight="bold"
              textAlign="center"
              sx={{ mb: 2, color: darkMode ? '#fff' : '#000' }}
            >
              {title}
            </Typography>
          )}

          {/* ── Form ──────────────────────────────────────────────────── */}
          <Box
            component="form"
            onSubmit={handleSubmit}
            sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}
          >
            {/* First Name & Last Name */}
            <Box sx={{ display: 'flex', gap: 1 }}>
              <TextField
                label="First Name"
                required
                fullWidth
                autoFocus
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
              />
              <TextField
                label="Last Name"
                required
                fullWidth
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
              />
            </Box>

            {/* Email */}
            <TextField
              label="Email"
              type="email"
              required
              fullWidth
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            {/* Password */}
            <TextField
              label="Password"
              type="password"
              required
              fullWidth
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            {/* Confirm Password */}
            <TextField
              label="Confirm Password"
              type="password"
              required
              fullWidth
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              error={confirmPasswordError}
              helperText={confirmPasswordError ? 'Passwords do not match' : ''}
            />

            {/* Error Message */}
            {error && (
              <Typography variant="body2" color="error" textAlign="center">
                {error}
              </Typography>
            )}

            {/* Submit Button */}
            <Button
              type="submit"
              variant="outlined"
              fullWidth
              disabled={isButtonDisabled}
              sx={{ mt: 1, py: 1.2 }}
            >
              {isLoading ? 'Creating Account...' : 'Sign Up With Credentials'}
            </Button>
          </Box>
        </Paper>
      </Box>
    </ThemeProvider>
  );
}

