import React, { useRef, useState, useCallback, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  ThemeProvider,
  CssBaseline,
  createTheme,
  IconButton,
} from '@mui/material';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';

// ─── 🌙 Toggle Dark Mode Here ────────────────────────────────────────────────
const DARK_MODE = false;

// ─── Sample Events Data ───────────────────────────────────────────────────────
const SAMPLE_EVENTS = [
  { event_id: '1', event_name: 'Stand-Up Comedy Night', event_city: 'Hyderabad', show_date: 'Sun, 12 Jul', show_onwards: false, emoji: '🎤' },
  { event_id: '2', event_name: 'Bhajan Jamming 4.0', event_city: 'Hyderabad', show_date: 'Sun, 12 Jul', show_onwards: true, emoji: '🎵' },
  { event_id: '3', event_name: 'The Jam Room Special', event_city: 'Hyderabad', show_date: 'Sun, 12 Jul', show_onwards: false, emoji: '🎸' },
  { event_id: '4', event_name: 'Comedy Standup Nights', event_city: 'Hyderabad', show_date: 'Sun, 12 Jul', show_onwards: true, emoji: '😂' },
  { event_id: '5', event_name: 'Live Music Festival', event_city: 'Hyderabad', show_date: 'Mon, 13 Jul', show_onwards: true, emoji: '🎶' },
  { event_id: '6', event_name: 'Gautham Govindan Live', event_city: 'Hyderabad', show_date: 'Sat, 1 Aug', show_onwards: false, emoji: '🎙️' },
  { event_id: '7', event_name: 'Masoom Vichar', event_city: 'Hyderabad', show_date: 'Sun, 12 Jul', show_onwards: true, emoji: '🃏' },
  { event_id: '8', event_name: 'Aakash Mehta Live', event_city: 'Hyderabad', show_date: 'Fri, 18 Jul', show_onwards: false, emoji: '🌟' },
];

// ─── Carousel Component ───────────────────────────────────────────────────────
function EventCarousel({ title, events }: { title: string; events: typeof SAMPLE_EVENTS }) {
  const scrollRef = useRef<HTMLDivElement>(null);

  // ── Arrow visibility state ─────────────────────────────────────────────
  const [showLeft, setShowLeft]   = useState(false);  // ← Hidden at start
  const [showRight, setShowRight] = useState(true);   // ← Visible at start

  // ── Check scroll position & update arrow visibility ───────────────────
  const updateArrows = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;

    const atStart = el.scrollLeft <= 0;
    const atEnd   = el.scrollLeft + el.clientWidth >= el.scrollWidth - 1; // -1 for rounding

    setShowLeft(!atStart);   // Show left arrow only if NOT at start
    setShowRight(!atEnd);    // Show right arrow only if NOT at end
  }, []);

  // ── Listen to scroll events ───────────────────────────────────────────
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;

    // Check on mount in case content doesn't overflow
    updateArrows();

    el.addEventListener('scroll', updateArrows, { passive: true });
    return () => el.removeEventListener('scroll', updateArrows);
  }, [updateArrows]);

  // ── Also update arrows if window resizes ─────────────────────────────
  useEffect(() => {
    window.addEventListener('resize', updateArrows);
    return () => window.removeEventListener('resize', updateArrows);
  }, [updateArrows]);

  // ── Scroll Handler ────────────────────────────────────────────────────
  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({
        left: direction === 'right' ? 600 : -600,
        behavior: 'smooth',
      });
    }
  };

  return (
    <Box sx={{ mb: 5 }}>

      {/* ── Section Header ─────────────────────────────────────────────── */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" fontWeight="bold">
          {title}
        </Typography>
        <Typography
          variant="body2"
          sx={{ color: '#e91e63', cursor: 'pointer', fontWeight: 500 }}
        >
          See All &rsaquo;
        </Typography>
      </Box>

      {/* ── Carousel Wrapper ────────────────────────────────────────────── */}
      <Box sx={{ position: 'relative' }}>

        {/* ── Left Arrow — hidden at start ─────────────────────────────── */}
        {showLeft && (
          <IconButton
            onClick={() => scroll('left')}
            sx={{
              position: 'absolute',
              left: -20,
              top: '40%',
              transform: 'translateY(-50%)',
              zIndex: 2,
              background: 'rgba(0,0,0,0.6)',
              color: '#fff',
              '&:hover': { background: 'rgba(0,0,0,0.9)' },
            }}
          >
            <ChevronLeftIcon />
          </IconButton>
        )}

        {/* ── Scrollable Cards Row ─────────────────────────────────────── */}
        <Box
          ref={scrollRef}
          sx={{
            display: 'flex',
            gap: 2,
            overflowX: 'auto',
            scrollbarWidth: 'none',
            '&::-webkit-scrollbar': { display: 'none' },
            pb: 1,
          }}
        >
          {events.map((event) => (
            <EventCard key={event.event_id} event={event} />
          ))}
        </Box>

        {/* ── Right Arrow — hidden at end ───────────────────────────────── */}
        {showRight && (
          <IconButton
            onClick={() => scroll('right')}
            sx={{
              position: 'absolute',
              right: -20,
              top: '40%',
              transform: 'translateY(-50%)',
              zIndex: 2,
              background: 'rgba(0,0,0,0.6)',
              color: '#fff',
              '&:hover': { background: 'rgba(0,0,0,0.9)' },
            }}
          >
            <ChevronRightIcon />
          </IconButton>
        )}

      </Box>
    </Box>
  );
}

// ─── Event Card Component ────────────────────────────────────────────────────
function EventCard({ event }: { event: typeof SAMPLE_EVENTS[0] }) {
  return (
    <Box
      sx={{
        minWidth: 180,
        maxWidth: 180,
        cursor: 'pointer',
        flexShrink: 0,
        '&:hover .card-image': {
          transform: 'scale(1.03)',
        },
      }}
    >
      <Box sx={{ position: 'relative', borderRadius: 2, overflow: 'hidden', mb: 1 }}>
        <Box
          className="card-image"
          sx={{
            height: 260,
            background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '64px',
            transition: 'transform 0.3s ease',
          }}
        >
          {event.emoji}
        </Box>

        <Box
          sx={{
            position: 'absolute',
            bottom: 0,
            left: 0,
            right: 0,
            background: 'rgba(0,0,0,0.65)',
            color: '#fff',
            px: 1.5,
            py: 0.5,
            fontSize: '12px',
            fontWeight: 500,
          }}
        >
          {event.show_date}{event.show_onwards ? ' onwards' : ''}
        </Box>
      </Box>

      <Typography
        variant="body2"
        fontWeight="bold"
        sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: '13px' }}
      >
        {event.event_name}
      </Typography>
      <Typography variant="caption" color="text.secondary" fontSize="12px">
        {event.event_city}
      </Typography>
    </Box>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────
export default function User_Home_Page() {
  const theme = React.useMemo(
    () => createTheme({ palette: { mode: DARK_MODE ? 'dark' : 'light' } }),
    []
  );

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ minHeight: '100vh', px: 5, py: 4 }}>
        <EventCarousel title="Popular Events" events={SAMPLE_EVENTS} />
        <EventCarousel title="Comedy Shows"   events={SAMPLE_EVENTS.slice(0, 5)} />
      </Box>
    </ThemeProvider>
  );
}

